import{_ as n,o as e,c as t,a2 as s}from"./chunks/framework.XXezeKOl.js";const g=JSON.parse('{"title":"面试题","description":"AI Agent 开发岗位常见面试题，分为基础概念、RAG、工程与系统设计三部分，附参考答案。","frontmatter":{"title":"面试题","description":"AI Agent 开发岗位常见面试题，分为基础概念、RAG、工程与系统设计三部分，附参考答案。"},"headers":[],"relativePath":"interview/index.md","filePath":"interview/index.md","lastUpdated":null}'),r={name:"interview/index.md"};function i(l,a,p,d,o,c){return e(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="面试题" tabindex="-1">面试题 <a class="header-anchor" href="#面试题" aria-label="Permalink to &quot;面试题&quot;">​</a></h1><p>这里整理了 AI Agent 开发、大模型应用开发岗位中经常被问到的问题。题目按主题分为三部分，每题都附有参考答案，点击展开即可查看。</p><table tabindex="0"><thead><tr><th>分类</th><th>内容</th><th>适合</th></tr></thead><tbody><tr><td><a href="/interview/basics">基础概念题</a></td><td>大模型原理、提示词、Tool Calling、Agent 循环、上下文与记忆、MCP</td><td>所有岗位</td></tr><tr><td><a href="/interview/rag">RAG 题</a></td><td>切分、Embedding、向量检索、混合检索与重排、评估与优化</td><td>知识库、搜索、企业助手方向</td></tr><tr><td><a href="/interview/engineering">工程与系统设计题</a></td><td>评估、可观测性、安全、成本、部署，以及完整的系统设计题</td><td>中高级工程师、架构师</td></tr></tbody></table><h2 id="怎么用这些题" tabindex="-1">怎么用这些题 <a class="header-anchor" href="#怎么用这些题" aria-label="Permalink to &quot;怎么用这些题&quot;">​</a></h2><ul><li><strong>先自己答，再看参考答案。</strong> 能用自己的话讲清楚，比背下答案有用得多。</li><li><strong>答案是提纲，不是标准。</strong> 面试官更看重你的思考过程和真实经验，参考答案里的要点可以作为检查清单。</li><li><strong>结合项目来答。</strong> 每个问题都尽量联系自己做过的东西，比如&quot;我在做知识库项目时遇到过……&quot;。如果还没有项目经验，可以从 <a href="/projects/">实战项目</a> 中挑几个做完。</li><li><strong>答不上来就回去读文章。</strong> 每页末尾列出了对应的知识模块。</li></ul><h2 id="面试官通常在考察什么" tabindex="-1">面试官通常在考察什么 <a class="header-anchor" href="#面试官通常在考察什么" aria-label="Permalink to &quot;面试官通常在考察什么&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  概念理解            工程能力               系统思维</span></span>
<span class="line"><span> ┌──────────┐      ┌──────────────┐      ┌────────────────┐</span></span>
<span class="line"><span> │ 原理讲得清 │ ──▶ │ 知道坑在哪里   │ ──▶ │ 能做权衡与取舍   │</span></span>
<span class="line"><span> │ 不混淆概念 │      │ 有排查和优化手段│      │ 考虑评估、安全、 │</span></span>
<span class="line"><span> │           │      │              │      │ 成本和可运维性   │</span></span>
<span class="line"><span> └──────────┘      └──────────────┘      └────────────────┘</span></span>
<span class="line"><span>   初级岗位重点        中级岗位重点            高级岗位重点</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>对于大多数岗位，最容易拉开差距的是两件事：<strong>你如何评估 Agent 的效果</strong>，以及 <strong>你如何处理 Agent 的失败</strong>。准备时建议重点阅读 <a href="/guide/14-evaluation/why-evals">为什么评估是第一优先级</a> 和 <a href="/guide/05-tool-calling/error-handling">工具错误处理与重试</a>。</p><p>术语不熟可以查 <a href="/glossary">术语表</a>。</p>`,9)])])}const b=n(r,[["render",i]]);export{g as __pageData,b as default};
